-- Mock transactional data for Q1-Q2 2026.
-- This script derives Reservation / Payment / Refund / PriceChangeLog
-- from the current Hotel + Room inventory.
-- FinancialLedger is generated by existing triggers when available,
-- and backfilled safely for any missing rows.

START TRANSACTION;

DELETE FROM FinancialLedger
WHERE ReferenceId LIKE 'PMT26%'
   OR ReferenceId LIKE 'RFD26%';

DELETE FROM Refund
WHERE RefundId LIKE 'RFD26%';

DELETE FROM Payment
WHERE PaymentId LIKE 'PMT26%';

DELETE FROM Reservation
WHERE ReservationId LIKE 'RSV26%';

DELETE FROM PriceChangeLog
WHERE LogId LIKE 'PCL26%';

DROP TEMPORARY TABLE IF EXISTS tmp_room_pool;
CREATE TEMPORARY TABLE tmp_room_pool (
    rn INT NOT NULL PRIMARY KEY,
    RoomId VARCHAR(10) NOT NULL,
    HotelId VARCHAR(24) NOT NULL,
    RoomType VARCHAR(100),
    BasePrice DECIMAL(18,2) NOT NULL,
    EffectivePrice DECIMAL(18,2) NOT NULL
);

INSERT INTO tmp_room_pool (
    rn,
    RoomId,
    HotelId,
    RoomType,
    BasePrice,
    EffectivePrice
)
SELECT
    ROW_NUMBER() OVER (ORDER BY r.HotelId, r.RoomId) AS rn,
    r.RoomId,
    r.HotelId,
    r.RoomType,
    r.BasePrice,
    COALESCE(NULLIF(r.CurrentPrice, 0), r.BasePrice) AS EffectivePrice
FROM Room r
INNER JOIN Hotel h ON h.HotelId = r.HotelId
WHERE COALESCE(r.Status, 1) = 1
  AND COALESCE(h.Status, 1) = 1;

SET @room_count := (SELECT COUNT(*) FROM tmp_room_pool);

